--changeset qltb:192-csvc-catalog
-- Danh mục CSVC chuẩn (QLTB-625, 626, 628). Gốc: file mẫu CSDL HCM (docs/du-an/5-Khao-sat/truong.hcm.edu.vn/
-- File_mau_phong_hoc_csvc.xlsx) — 9 khối, 54 loại; khối 01, 02 chỉ cho mầm non nên không nạp (dự án bỏ mầm non).
--
-- Khối CSVC = bảng mới `facility_groups`. Loại CSVC = mở rộng `room_types` (không tách bảng mới: phòng, định mức
-- thiết bị, báo cáo đều đã trỏ vào đây). Mỗi loại mang:
--   group_id    khối;
--   kind        ROOM (phòng, nhà) | AREA (khu vực, công trình không phải phòng: sân, cổng, khu vệ sinh, để xe…);
--   levels      cấp áp dụng, mã cấp học cách nhau dấu phẩy ('TH,THCS'); trống = mọi cấp;
--   standard    thuộc danh mục theo văn bản (Sở quản lý) — false là loại ngoài danh mục;
--   legal_basis văn bản căn cứ (phiên bản theo văn bản: loại hết hiệu lực thì ngừng dùng, loại mới thêm theo văn bản mới);
--   loanable    phòng thuộc loại này mặc định cho mượn (thay danh sách mã cố định trong RoomService / facility-extra);
--   functional  phòng bộ môn / chức năng — báo cáo Sử dụng phòng chỉ tính các loại này (thay FUNCTIONAL_ROOMS);
--   school_id   trường đã thêm loại ngoài danh mục (QLTB-629); trống = loại dùng chung.
--
-- 8 loại cũ: 6 loại đổi tên tại chỗ thành loại chuẩn (giữ mã, giữ id — phòng không phải đổi); phòng của "Phòng bộ
-- môn" / "Phòng thí nghiệm" chuyển sang loại phòng bộ môn theo MÔN của phòng; phòng chưa ghép được giữ loại cũ, loại
-- cũ thành ngoài danh mục (standard = false), không còn phòng nào thì ngừng dùng.
CREATE TABLE facility_groups (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_facility_groups PRIMARY KEY,
    code          VARCHAR(64)  NOT NULL CONSTRAINT uq_facility_groups_code UNIQUE,
    name          VARCHAR(255) NOT NULL,
    levels        VARCHAR(40),
    sort_order    INTEGER,
    active        BOOLEAN      NOT NULL DEFAULT TRUE,
    note          VARCHAR(500),
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at    TIMESTAMP WITH TIME ZONE,
    created_by_id BIGINT CONSTRAINT fk_facility_groups_created_by REFERENCES users (id) ON DELETE SET NULL,
    updated_by_id BIGINT CONSTRAINT fk_facility_groups_updated_by REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX idx_facility_groups_sort ON facility_groups (sort_order, name);

INSERT INTO facility_groups (code, name, sort_order, active, created_at) VALUES
    ('03', 'Khối phụ trợ', 30, TRUE, now()),
    ('04', 'Khối phòng hành chính quản trị', 40, TRUE, now()),
    ('05', 'Khối phòng học tập', 50, TRUE, now()),
    ('06', 'Khối phòng hỗ trợ học tập', 60, TRUE, now()),
    ('07', 'Khu sân chơi, thể dục thể thao', 70, TRUE, now()),
    ('08', 'Khối phục vụ sinh hoạt', 80, TRUE, now()),
    ('09', 'Khối phòng khác', 90, TRUE, now());

ALTER TABLE room_types
    ADD COLUMN group_id    BIGINT CONSTRAINT fk_room_types_group REFERENCES facility_groups (id) ON DELETE RESTRICT,
    ADD COLUMN kind        VARCHAR(10)  NOT NULL DEFAULT 'ROOM' CONSTRAINT ck_room_types_kind CHECK (kind IN ('ROOM', 'AREA')),
    ADD COLUMN levels      VARCHAR(40),
    ADD COLUMN standard    BOOLEAN      NOT NULL DEFAULT FALSE,
    ADD COLUMN legal_basis VARCHAR(255),
    ADD COLUMN loanable    BOOLEAN      NOT NULL DEFAULT FALSE,
    ADD COLUMN functional  BOOLEAN      NOT NULL DEFAULT FALSE,
    ADD COLUMN school_id   BIGINT CONSTRAINT fk_room_types_school REFERENCES schools (id) ON DELETE RESTRICT;
CREATE INDEX idx_room_types_group ON room_types (group_id);
CREATE INDEX idx_room_types_school ON room_types (school_id);

