-- Phòng bộ môn / thí nghiệm cũ: chuyển sang loại phòng bộ môn theo môn của phòng.
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng học bộ môn Âm nhạc') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('âm nhạc')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng học bộ môn Mỹ thuật') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('mỹ thuật')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng học bộ môn Khoa học – Công nghệ') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('khoa học (tiểu học)', 'khoa học')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng học bộ môn Tin học') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('tin học')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng học bộ môn Ngoại ngữ') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('tiếng anh', 'ngoại ngữ', 'ngoại ngữ khác', 'tiếng pháp', 'tiếng nhật', 'tiếng trung', 'tiếng hàn', 'tiếng đức', 'tiếng nga')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng học bộ môn Công nghệ') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('công nghệ')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng học bộ môn Khoa học tự nhiên') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('khoa học tự nhiên')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng học bộ môn Khoa học xã hội') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('lịch sử và địa lí', 'lịch sử và địa lý', 'khoa học xã hội')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng bộ môn Vật lý') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('vật lý', 'vật lí')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng bộ môn Hóa học') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('hóa học', 'hoá học')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));
UPDATE rooms r SET room_type_id = (SELECT id FROM room_types WHERE lower(name) = lower('Phòng bộ môn Sinh học') AND school_id IS NULL ORDER BY id LIMIT 1), updated_at = now()
FROM subjects s WHERE s.id = r.subject_id AND lower(s.name) IN ('sinh học')
  AND r.room_type_id IN (SELECT id FROM room_types WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM'));

-- Loại cũ còn lại: ngoài danh mục, vẫn là phòng bộ môn (cho mượn, tính vào báo cáo sử dụng); hết phòng thì ngừng.
UPDATE room_types SET group_id = (SELECT id FROM facility_groups WHERE code = '05'), standard = FALSE, loanable = TRUE,
    functional = TRUE, note = 'Loại cũ — đổi phòng sang loại phòng bộ môn theo môn.', updated_at = now(),
    active = EXISTS (SELECT 1 FROM rooms r WHERE r.room_type_id = room_types.id)
WHERE code IN ('PHONG_BO_MON', 'PHONG_THI_NGHIEM');

-- Loại khác (không thuộc 8 loại cũ, không trùng tên chuẩn): giữ, ngoài danh mục, mặc định cho mượn như trước
-- (RoomService cũ cho mượn mọi loại ngoài KHO / PHONG_HOC / THU_VIEN / KHAC).
UPDATE room_types SET loanable = TRUE WHERE group_id IS NULL;

