--changeset qltb:192-csvc-catalog-permissions
INSERT INTO permissions (code, name, description, system_permission) VALUES
    ('facility_groups:read',   'Xem khối CSVC', 'Xem danh sách và chi tiết khối CSVC', TRUE),
    ('facility_groups:write',  'Sửa khối CSVC', 'Thêm và sửa khối CSVC',               TRUE),
    ('facility_groups:delete', 'Xoá khối CSVC', 'Xoá vĩnh viễn một khối CSVC',         TRUE);

-- Đọc: mọi vai đọc được loại phòng.
INSERT INTO role_permissions (role_id, permission_id)
SELECT DISTINCT rp.role_id, p.id
FROM role_permissions rp
JOIN permissions old ON old.id = rp.permission_id AND old.code = 'room_types:read'
CROSS JOIN permissions p
WHERE p.code = 'facility_groups:read';

-- Sửa, xoá: ai đang sửa / xoá được loại phòng.
INSERT INTO role_permissions (role_id, permission_id)
SELECT DISTINCT rp.role_id, p.id
FROM role_permissions rp
JOIN permissions old ON old.id = rp.permission_id AND old.code = 'room_types:write'
CROSS JOIN permissions p
WHERE p.code = 'facility_groups:write';
INSERT INTO role_permissions (role_id, permission_id)
SELECT DISTINCT rp.role_id, p.id
FROM role_permissions rp
JOIN permissions old ON old.id = rp.permission_id AND old.code = 'room_types:delete'
CROSS JOIN permissions p
WHERE p.code = 'facility_groups:delete';

